package com.jobradar.taxonomy.location;import java.util.Set;import com.jobradar.common.api.PaginatedResponse;import com.jobradar.common.exception.*;import com.jobradar.common.pagination.PaginationParameters;import com.jobradar.taxonomy.common.TaxonomySupport;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)public class LocationService{private static final Set<String>SORTS=Set.of("city","state","country","opportunityCount","createdAt");private final LocationRepository repo;public LocationService(LocationRepository r){repo=r;}public PaginatedResponse<LocationDto> browse(String q,PaginationParameters p,boolean admin){String sort=p.getSort().equals("createdAt")?"city":p.getSort();Pageable pageable=TaxonomySupport.pageable(replace(p,sort),SORTS,"city");Page<LocationEntity> page=admin?repo.adminBrowse(blank(q),pageable):repo.browse(blank(q),pageable);return PaginatedResponse.from(page.map(LocationDto::from));}private PaginationParameters replace(PaginationParameters p,String sort){p.setSort(sort);return p;}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}@Transactional public LocationDto create(LocationRequest r){String c=r.city().trim(),s=blank(r.state()),co=r.country().trim();TaxonomySupport.duplicate(repo.duplicate(c,s,co,null),"Location");return LocationDto.from(repo.save(new LocationEntity(c,s,co)));}@Transactional public LocationDto update(Integer id,LocationRequest r){LocationEntity e=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Location not found"));String c=r.city().trim(),s=blank(r.state()),co=r.country().trim();TaxonomySupport.duplicate(repo.duplicate(c,s,co,id),"Location");e.update(c,s,co);return LocationDto.from(e);}@Transactional public void active(Integer id,boolean a){repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Location not found")).setActive(a);}}
